import pandas as pd, numpy as np
lab_path='/root/environment/data/ckd_lab_data.csv'
df=pd.read_csv(lab_path, dtype=str)

def parse_num(s):
    if pd.isna(s): return np.nan
    s=str(s).strip()
    if s=='' or s.lower() in {'na','nan','none','null'}: return np.nan
    if ',' in s and '.' in s:
        s=s.replace(',','')
    else:
        s=s.replace(',','.')
    try:
        return float(s)
    except:
        return np.nan

cols=['Hematocrit','RBC_Count','WBC_Count','Platelet_Count','Ionized_Calcium','Phosphorus','BNP','NT_proBNP','Troponin_I','Troponin_T','Free_T4','Free_T3']
for c in cols:
    s=df[c].map(parse_num)
    q=s.quantile([0,0.01,0.05,0.5,0.95,0.99,1])
    print('\n',c)
    print(q)
PY", "timeout": 100000, "security_risk": "LOW", "summary": "Compute quantiles for additional labs to infer units"}

