def parse_num(s):
    if pd.isna(s): return np.nan
    s=str(s).strip()
    if s=='' or s.lower() in {'na','nan','none','null'}: return np.nan
    if ',' in s and '.' in s:
        s=s.replace(',','')
    else:
        s=s.replace(',','.')
    try:
        return float(s)
    except:
        return np.nan

raw=pd.read_csv('/root/environment/data/ckd_lab_data.csv', dtype=str)
num=raw.copy()
for c in raw.columns:
    if c=='patient_id':
        num[c]=pd.to_numeric(raw[c], errors='coerce')
    else:
        num[c]=raw[c].map(parse_num)
print('rows original',len(num))
print('rows complete (no NaN)',len(num.dropna()))
